package dev.zomboid.hordes;
import fixture.Game.*;import java.util.*;import net.minecraft.world.item.ItemStack;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.entity.EquipmentSlot;import net.minecraft.world.entity.item.ItemEntity;import lain.mods.cos.api.CosArmorAPI;import de.maxhenkel.corpse.entities.CorpseEntity;
public class CorpseChecks{
 static int checks;static void ok(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}static ItemStack item(String id){return new ItemStack(id,1,"attachments-ammo-durability");}
 static class Setup{Level l=new Level();ServerPlayer p=new ServerPlayer(l);Zombie z=new Zombie(l);Cosmetic cos;Setup(){PlayerCorpse43.PENDING.clear();p.cap.zombie=z;z.owner=p.uuid;p.equipment.set(0,item("rifle"));p.equipment.set(5,item("helmet"));p.cargo.add(item("rifle"));p.cargo.add(item("helmet"));p.cargo.add(new ItemStack("ammo",64,"556"));z.cargo.addAll(p.cargo);cos=CosArmorAPI.getCAStacks(p.uuid);cos.items.set(3,item("cosmetic_helmet"));}void capture(){PlayerCorpse43.capture(new Event(p));}void spawn(){l.entities.put(z.uuid,z);PlayerCorpse43.join(z);}Event drops(){Event e=new Event(z);for(ItemStack s:z.cargo)e.drops.add(new ItemEntity(l,2,65,3,s.copy()));return e;}}
 static int count(CorpseEntity c,String id){return c.getDeath().items.stream().filter(s->s.id.equals(id)).mapToInt(s->s.count).sum();}
 public static void main(String[]args){
  Setup s=new Setup();s.capture();ok(s.cos.getStackInSlot(3).id.equals("cosmetic_helmet"),"capture does not consume cosmetics");s.spawn();ok(s.z.equipment.get(5).id.equals("cosmetic_helmet"),"cosmetic visible over normal helmet");ok(s.z.equipment.get(0).id.equals("rifle"),"player weapon equipped");PlayerCorpse43.tick();ok(s.cos.getStackInSlot(3).isEmpty()&&s.z.cargo.size()==4,"move cosmetic source exactly once");for(int i=0;i<5;i++)PlayerCorpse43.tick();ok(s.z.cargo.size()==4,"no repeated cosmetic copies");Event e=s.drops();PlayerCorpse43.drops(e);ok(e.canceled&&e.drops.isEmpty()&&s.z.cargo.isEmpty(),"native drops suppressed after Corpse commit");ok(s.l.corpses.size()==1,"exactly one real Corpse entity");CorpseEntity c=s.l.corpses.get(0);ok(c.owner.equals(s.p.uuid)&&count(c,"helmet")==1&&count(c,"cosmetic_helmet")==1&&count(c,"ammo")==64,"owner and all owned equipment retained");ok(c.display.get(5).id.equals("cosmetic_helmet")&&c.display.get(0).id.equals("rifle"),"corpse appearance matches zombie");ok(c.getDeath().items.stream().filter(v->v.id.equals("rifle")).findFirst().get().components.equals("attachments-ammo-durability"),"components retained");PlayerCorpse43.drops(new Event(s.z));ok(s.l.corpses.size()==1,"repeated drops event cannot duplicate corpse");
  s=new Setup();s.capture();s.spawn();e=s.drops();PlayerCorpse43.drops(e);ok(s.cos.getStackInSlot(3).isEmpty()&&count(s.l.corpses.get(0),"cosmetic_helmet")==1,"same-tick kill includes deferred cosmetics");
  s=new Setup();s.capture();s.spawn();s.l.reject=true;e=s.drops();int original=e.drops.size();PlayerCorpse43.drops(e);ok(!e.canceled&&e.drops.size()==original+1&&s.l.corpses.isEmpty()&&!s.z.cargo.isEmpty(),"failed spawn leaves native drops including late cosmetics");
  s=new Setup();s.capture();s.spawn();s.z.cargo.add(s.cos.items.get(3).copy());s.cos.items.set(3,ItemStack.EMPTY);PlayerCorpse43.tick();e=s.drops();PlayerCorpse43.drops(e);ok(count(s.l.corpses.get(0),"cosmetic_helmet")==1,"already dropped cosmetics not duplicated");
  s=new Setup();s.l.rules.keep=true;s.z.cargo.clear();s.capture();s.spawn();PlayerCorpse43.tick();e=s.drops();PlayerCorpse43.drops(e);ok(!s.cos.items.get(3).isEmpty()&&s.l.corpses.get(0).getDeath().items.isEmpty(),"keep inventory respected without preview duplication");
  s=new Setup();s.capture();for(int i=0;i<45;i++)PlayerCorpse43.tick();ok(!s.cos.items.get(3).isEmpty()&&PlayerCorpse43.PENDING.isEmpty(),"never consume source for rejected zombie spawn");
  s=new Setup();s.capture();s.spawn();s.cos.items.set(3,item("new_respawn_helmet"));PlayerCorpse43.tick();ok(s.cos.items.get(3).id.equals("new_respawn_helmet")&&s.z.cargo.size()==3,"do not steal replacement cosmetic gear");
  s=new Setup();s.spawn();e=s.drops();PlayerCorpse43.drops(e);ok(s.l.corpses.size()==1&&count(s.l.corpses.get(0),"rifle")==1,"legacy stored player zombie cargo recovered without snapshot");
  Event ordinary=new Event(new Entity(new Level()));ordinary.drops.add(new ItemEntity(ordinary.entity.level(),0,0,0,item("test")));PlayerCorpse43.drops(ordinary);ok(!ordinary.canceled&&ordinary.drops.size()==1,"ordinary mobs untouched");
  s=new Setup();s.capture();s.spawn();s.cos.failAfter=true;e=s.drops();PlayerCorpse43.drops(e);ok(s.l.corpses.size()==1&&count(s.l.corpses.get(0),"cosmetic_helmet")==1&&s.cos.items.get(3).isEmpty(),"listener failure after clear preserves single ownership");
  for(int mask=0;mask<64;mask++){
   s=new Setup();for(int slot=0;slot<6;slot++)if((mask&(1<<slot))!=0){ItemStack v=new ItemStack("gear_"+slot,1,"tag_"+mask);s.p.equipment.set(slot,v);s.z.cargo.add(v.copy());}
   for(int n=0;n<100;n++)s.z.cargo.add(new ItemStack("cargo_"+n,1+n%64,"nested:"+mask+":"+n));
   Map<String,Integer>expected=new TreeMap<>();for(ItemStack v:s.z.cargo)expected.merge(v.id+"#"+v.components,v.count,Integer::sum);expected.merge("cosmetic_helmet#attachments-ammo-durability",1,Integer::sum);
   s.capture();s.spawn();PlayerCorpse43.tick();
   // Simulate unload/save metadata and native stored inventory; no pending live-player reference.
   Zombie restored=new Zombie(s.l);restored.owner=s.z.owner;restored.tag=s.z.tag.copy();for(ItemStack v:s.z.cargo)restored.cargo.add(v.copy());s.l.entities.put(restored.uuid,restored);PlayerCorpse43.join(restored);s.z=restored;e=s.drops();PlayerCorpse43.drops(e);Map<String,Integer>actual=new TreeMap<>();for(ItemStack v:s.l.corpses.get(0).getDeath().items)actual.merge(v.id+"#"+v.components,v.count,Integer::sum);ok(expected.equals(actual),"all counts and nested components survive stored zombie route "+mask);ok(s.l.corpses.get(0).getDeath().items.size()>100,"no 27/54-slot truncation "+mask);
  }
  ok(dev.zomboid.remains.PlayerZombieGuard43.entity(s.z)&&!dev.zomboid.remains.PlayerZombieGuard43.entity(new Entity(s.l)),"only player zombie bypasses remains");
  System.out.println("PLAYER_CORPSE_CHECKS="+checks);
 }
}
